Modelica source:
```modelica
connector Pin
  Real v;
  flow Real i;
end Pin;
model DriverCore
  parameter Real drive=3;
  parameter Real slope=1;
  Pin p;
  Real x;
equation
  p.v=drive+slope*x;
  p.i=x;
end DriverCore;
model LoadCore
  parameter Real gain=5;
  parameter Real shift=1;
  Pin p;
  Real y;
equation
  p.v=gain*y+shift;
  p.i=-y;
end LoadCore;
model TunedDriver
  extends DriverCore;
end TunedDriver;
model Bridge
  parameter Real offset=1;
  parameter Real ratio=2;
  Pin a;
  Pin b;
  Real z;
equation
  a.v=b.v+offset+ratio*z;
  a.i=z;
  b.i=-z;
end Bridge;
model Study
  TunedDriver d(drive=5);
  LoadCore l;
  Bridge b;
  Bridge b2(offset=2, ratio=3);
equation
  connect(d.p,b.a);
  connect(b.b,b2.a);
  connect(b2.b,l.p);
end Study;
```

